import argparse,hashlib,json
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument("input");p.add_argument("resolver");p.add_argument("output");a=p.parse_args();d=json.loads(Path(a.input).read_text());cash=sum(x["amount"] for x in d["bank_entries"]);liab=sum(x["amount"] for x in d["ap"])+sum(x["current_portion"] for x in d["debt"])
items=[{"proposition":"transaction identity","status":"SUPPORTED_WITH_CONFLICT"},{"proposition":"account ownership","status":"MISSING","support":[]},{"proposition":"invoice validity","status":"SUPPORTED_AS_RECORD_ONLY"},{"proposition":"revenue recognition","status":"UNRESOLVED"},{"proposition":"cash availability","status":"MEASURED_BUT_OWNERSHIP_UNRESOLVED","amount":cash},{"proposition":"liability existence","status":"SUPPORTED_FOR_LISTED_ITEMS","amount":liab},{"proposition":"financial-statement classification","status":"UNRESOLVED"}]
out={"stage":"AccountingBoundary","input_sha256":hashlib.sha256(Path(a.input).read_bytes()).hexdigest(),"measured_cash_usd":cash,"measured_current_liabilities_usd":liab,"items":items,"boundaries":["transaction identity != account ownership","invoice validity != revenue recognition","cash availability != covenant compliance","liability existence != financial-statement classification"],"status":"REVIEW_REQUIRED"};Path(a.output).write_text(json.dumps(out,sort_keys=True,indent=2)+"\n");print(json.dumps({"stage":out["stage"],"status":out["status"],"cash":cash,"current_liabilities":liab}))
